mapper.select:
SELECT r.report_id, u.user_name AS target_name, r.report_type, r.reason, r.created_at, r.report_status FROM ctg_report r LEFT JOIN ctg_users u ON r.target_id = u.user_id
u.user_name LIKE CONCAT('%', #{keyword}, '%')
AND r.report_type = #{reportType}
AND r.report_status = #{reportStatus}
ORDER BY r.created_at DESC

mapper.update:
UPDATE ctg_report
SET status = #{status}
WHERE report_id = #{reportId};
